const fs=require('fs'),path=require('path'),sharp=require('sharp');
const root=path.resolve(__dirname,'..'),out=path.join(root,'marketing/assets',process.argv[2]||'figma-global-collection-20261010');
(async()=>{const report=JSON.parse(fs.readFileSync(path.join(out,'analysis.json'),'utf8'));let done=0;
async function render(item){const dir=path.dirname(path.join(root,item.svg));if(item.external_refs.some(ref=>!ref.startsWith('data:image/'))||item.missing_refs.length){item.render_status='held-external-or-missing';return;}
try{const file=path.join(dir,'preview.png');const png=fs.existsSync(file)?fs.readFileSync(file):await sharp(path.join(dir,'logo.svg'),{density:144,limitInputPixels:40000000}).resize({width:640,height:640,fit:'inside'}).png().toBuffer();if(!fs.existsSync(file))fs.writeFileSync(file,png);const meta=await sharp(png).metadata();const stats=await sharp(png).ensureAlpha().stats();item.preview_bytes=png.length;item.preview_dimensions=[meta.width,meta.height];item.alpha_min=stats.channels[3].min;item.alpha_max=stats.channels[3].max;item.render_status=stats.channels[3].max===0?'empty':stats.channels[3].min===255?'opaque-review':'rendered-alpha';done++;if(done%100===0)console.log('Rendered',done,'/',report.items.length);}catch(e){item.render_status='failed';item.error=e.message;console.log(item.id,e.message);if(done===0)throw e;}}
let cursor=0;await Promise.all(Array.from({length:4},async()=>{while(cursor<report.items.length){const item=report.items[cursor++];await render(item);}}));
fs.writeFileSync(path.join(out,'analysis.json'),JSON.stringify(report,null,2));console.log('Finished',done);})().catch(e=>{console.error(e);process.exitCode=1;});
